  --c2-seperator--style: dotted;
  --c2-seperator--thickness: 2px;
  --c2-seperator--color: #a1a1aa;
}

.accent {
  width: 240px;
  --c2-seperator--thickness: 3px;
  --c2-seperator--color: #0265dc;
}

.heading {
  width: 240px;
  --c2-seperator__line-start--flex: 0 0 0px;
  --c2-seperator__label--gap: 0px;
  --c2-seperator__label--color: #18181b;
  --c2-seperator__label--font-weight: 600;
  --c2-seperator__label--font-size: 11px;
  --c2-seperator__label--text-transform: uppercase;
  --c2-seperator__label--letter-spacing: 0.06em;
}
.heading::part(line) {
  margin-left: 12px;
}

.leading {
  width: 240px;
  --c2-seperator__line-start--flex: 0 0 24px;
  --c2-seperator__label--color: #3f3f46;
  --c2-seperator__label--font-size: 13px;
  --c2-seperator__label--font-weight: 400;
}

.badge-label {
  width: 240px;
  --c2-seperator__label--gap: 8px;
}

.toolbar {
  display: flex;
  align-items: center;
  gap: 12px;
  height: 36px;
  padding: 0 14px;
  border: 1px solid #e4e4e7;
  border-radius: 8px;
  font-size: 13px;
  color: #3f3f46;
}

.dark {
  display: grid;
  gap: 14px;
  width: 240px;
  padding: 16px;
  border-radius: 12px;
  background: #18181b;
  color: #a1a1aa;
  font-size: 13px;
  --c2-seperator--color: #3f3f46;
  --c2-seperator__label--color: #71717a;
}

.frame {
  position: relative;
  width: 100%;
  height: 240px;
  border: 1px solid #e4e4e7;
  border-radius: 10px;
  overflow: hidden;
  background: #ffffff;
  font-size: 14px;
}
.frame c2-side-nav {
  height: 100%;
}
.frame.tall {
  height: 300px;
}
.page {
  padding: 12px 16px;
}
.bar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.bar strong {
  font-size: 14px;
}
.menu {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border: 1px solid #d4d4d8;
  border-radius: 6px;
  background: #ffffff;
  color: #18181b;
  cursor: pointer;
}
.menu:hover {
  background: #f4f4f5;
}
.menu svg {
  width: 16px;
  height: 16px;
}
.muted {
  color: #71717a;
  font-size: 13px;
  line-height: 1.5;
  margin: 0;
}
.nav {
  width: 100%;
  --c2-list--background: transparent;
  --c2-list--padding-left: 0px;
  --c2-list--padding-right: 0px;
  --c2-list--padding-top: 0px;
  --c2-list--padding-bottom: 0px;
  --c2-list-item--padding-left: 10px;
  --c2-list-item--padding-right: 10px;
  --c2-list-item__hover--background: #eeeef0;
}
.brand {
  display: block;
  font-weight: 600;
  font-size: 13px;
  margin: 0 0 10px 10px;
}
.contained {
  --c2-side-nav__over--position: absolute;
  --c2-side-nav__over--height: 100%;
  --c2-side-nav__open--width: 200px;
}
.icon-rail {
  --c2-side-nav__close--width: 56px;
  --c2-side-nav__open--width: 210px;
  --c2-side-nav--padding-top: 8px;
  --c2-side-nav--padding-right: 8px;
  --c2-side-nav--padding-bottom: 8px;
  --c2-side-nav--padding-left: 8px;
}
.icon-rail .rail-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
  padding-left: 4px;
}
.icon-rail .logo {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: #18181b;
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
}
.icon-rail .label {
  white-space: nowrap;
  transition: opacity 200ms ease;
}
.icon-rail:not([opened]) .label {
  opacity: 0;
}
.icon-rail .collapse {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 32px;
  height: 32px;
  margin-left: auto;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: #71717a;
  cursor: pointer;
}
.icon-rail .collapse:hover {
  background: #eeeef0;
  color: #18181b;
}
.icon-rail .collapse svg {
  width: 16px;
  height: 16px;
}
.icon-rail:not([opened]) .rail-header {
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}
.icon-rail:not([opened]) .collapse {
  margin-left: 0;
}
.icon-rail .when-closed {
  display: none;
}
.icon-rail:not([opened]) .when-closed {
  display: block;
}
.icon-rail:not([opened]) .when-open {
  display: none;
}
.icon-rail .nav {
  --c2-list-item--padding-left: 12px;
  --c2-list-item--padding-right: 10px;
  --c2-list-item--gap: 12px;
  --c2-list-item__icon--size: 16px;
}
.icon-rail .nav c2-list-item {
  white-space: nowrap;
}
.icon-rail .badge {
  width: auto;
  height: auto;
  padding: 1px 6px;
  border-radius: 999px;
  background: #476ef9;
  color: #ffffff;
  font-size: 11px;
  font-weight: 600;
  line-height: 16px;
  transition: opacity 200ms ease;
}
.icon-rail:not([opened]) .badge {
  opacity: 0;
}

